-- RN-FRM-07: Carga oficial de la versión inicial V1.0.0 del formulario SIECA (8 secciones)
INSERT INTO formulario_version (
    id,
    codigo,
    esquema,
    mapeo,
    estado,
    publicada_en,
    creado_en,
    actualizado_en
) VALUES (
    '0192b000-0000-7000-8000-000000000001'::uuid,
    'V1.0.0',
    '{"$schema": "http://json-schema.org/draft-07/schema#", "title": "Formulario de Evaluación Técnica de Puentes (Manual Regional SIECA)", "description": "Versión 1.0.0 Oficial del Sistema de Gestión de Puentes. Cubre las 8 secciones normativas, delimitación de datos permanentes del inventario y matriz de daños en escala 0-4 para el Índice de Condición.", "type": "object", "required": ["identificacion", "datos_generales", "subestructura", "superestructura", "elementos_no_estructurales", "caracteristicas_cauce"], "properties": {"identificacion": {"type": "object", "title": "Sección 1: Identificación del Puente", "description": "Datos de localización física, clasificación vial y división político-administrativa (RN-INV-01 / RN-INS-09).", "required": ["codigo", "nombre", "ruta", "departamento", "municipio"], "properties": {"codigo": {"type": "string", "title": "Código INE del Puente", "description": "Formato GT-DEPTO-MUNI-NNNN generado por el módulo de inventario.", "readOnly": true, "x-permanente": true, "x-elemento-ref": "identificacion.codigo", "x-orden": 1}, "nombre": {"type": "string", "title": "Nombre del Puente", "readOnly": true, "x-permanente": true, "x-elemento-ref": "identificacion.nombre", "x-orden": 2}, "ruta": {"type": "string", "title": "Identificador de Ruta Vial", "readOnly": true, "x-permanente": true, "x-elemento-ref": "identificacion.ruta", "x-orden": 3}, "kilometraje": {"type": "number", "title": "Kilometraje (Estacionamiento)", "x-permanente": true, "x-unidad": "km", "x-elemento-ref": "identificacion.kilometraje", "x-orden": 4}, "departamento": {"type": "string", "title": "Departamento", "readOnly": true, "x-permanente": true, "x-elemento-ref": "identificacion.departamento", "x-orden": 5}, "municipio": {"type": "string", "title": "Municipio", "readOnly": true, "x-permanente": true, "x-elemento-ref": "identificacion.municipio", "x-orden": 6}, "tipo_pavimento": {"type": "string", "title": "Tipo de Pavimento de la Ruta", "enum": ["Asfalto", "Concreto Hidráulico", "Adoquín", "Terracería", "Mixto"], "x-permanente": true, "x-elemento-ref": "identificacion.tipo_pavimento", "x-orden": 7}, "alineamiento_horizontal": {"type": "string", "title": "Alineamiento Horizontal", "enum": ["Tangente", "Curva"], "x-permanente": true, "x-elemento-ref": "identificacion.alineamiento_horizontal", "x-orden": 8}, "tiene_esviaje": {"type": "boolean", "title": "¿Tiene Esviaje / Sesgo?", "x-permanente": true, "x-elemento-ref": "identificacion.tiene_esviaje", "x-orden": 9}, "poblacion_anterior": {"type": "string", "title": "Población ANTES del Puente", "x-permanente": true, "x-elemento-ref": "identificacion.poblacion_anterior", "x-orden": 10}, "poblacion_posterior": {"type": "string", "title": "Población DESPUÉS del Puente", "x-permanente": true, "x-elemento-ref": "identificacion.poblacion_posterior", "x-orden": 11}}}, "datos_generales": {"type": "object", "title": "Sección 2: Datos Generales y Geometría", "description": "Dimensiones físicas principales del puente y tipología constructiva.", "required": ["longitud_total", "numero_tramos", "ancho_rodadura"], "properties": {"longitud_total": {"type": "number", "minimum": 1, "title": "Longitud Total del Puente (m)", "x-permanente": true, "x-unidad": "m", "x-elemento-ref": "datos_generales.longitud_total", "x-orden": 1}, "numero_tramos": {"type": "integer", "minimum": 1, "title": "Número de Tramos", "x-permanente": true, "x-elemento-ref": "datos_generales.numero_tramos", "x-orden": 2}, "ancho_rodadura": {"type": "number", "minimum": 1, "title": "Ancho de Calzada de Rodadura (m)", "x-permanente": true, "x-unidad": "m", "x-elemento-ref": "datos_generales.ancho_rodadura", "x-orden": 3}, "ancho_acera_derecha": {"type": "number", "minimum": 0, "title": "Ancho de Acera Derecha (m)", "x-permanente": true, "x-unidad": "m", "x-elemento-ref": "datos_generales.ancho_acera_derecha", "x-orden": 4}, "ancho_acera_izquierda": {"type": "number", "minimum": 0, "title": "Ancho de Acera Izquierda (m)", "x-permanente": true, "x-unidad": "m", "x-elemento-ref": "datos_generales.ancho_acera_izquierda", "x-orden": 5}, "tipo_estructura": {"type": "string", "title": "Tipo de Estructura Principal", "enum": ["Vigas", "Losa", "Arco", "Armadura", "Atirantado", "Colgante", "Cajón"], "x-permanente": true, "x-elemento-ref": "datos_generales.tipo_estructura", "x-orden": 6}, "material_predominante": {"type": "string", "title": "Material Predominante", "enum": ["Concreto Reforzado", "Concreto Presforzado", "Acero Estructural", "Madera", "Mampostería", "Mixto"], "x-permanente": true, "x-elemento-ref": "datos_generales.material_predominante", "x-orden": 7}}}, "tramos": {"type": "array", "title": "Sección 3: Tramos Individuales", "description": "Detalle geométrico y estructural por cada tramo o claro del puente.", "items": {"type": "object", "required": ["numero_tramo", "longitud"], "properties": {"numero_tramo": {"type": "integer", "minimum": 1, "title": "Número de Tramo", "x-elemento-ref": "tramos.numero_tramo"}, "longitud": {"type": "number", "minimum": 0.5, "title": "Longitud del Tramo (m)", "x-unidad": "m", "x-elemento-ref": "tramos.longitud"}, "tipo_tramo": {"type": "string", "title": "Tipo de Tramo", "enum": ["Simplemente Apoyado", "Continuo", "Voladizo", "Empotrado"], "x-elemento-ref": "tramos.tipo_tramo"}, "galibo_vertical": {"type": "number", "minimum": 0, "title": "Gálibo / Espacio Libre Vertical (m)", "x-unidad": "m", "x-elemento-ref": "tramos.galibo_vertical"}}}}, "subestructura": {"type": "object", "title": "Sección 4: Sub-estructura", "description": "Evaluación de estribos, pilas y cimentaciones (escala de daño 0 a 4). Alimenta el IC de P8.", "required": ["estribo_entrada_grietas", "estribo_entrada_socavacion", "estribo_salida_grietas", "estribo_salida_socavacion", "pilas_grietas", "pilas_socavacion", "asentamiento_estructural"], "properties": {"estribo_entrada_grietas": {"type": "integer", "minimum": 0, "maximum": 4, "title": "Estribo de Entrada: Fisuras o grietas en cortina y aleros", "description": "0=Sin daño, 1=Incipiente (<1mm), 2=Moderado (1-3mm), 3=Severo (>3mm), 4=Falla estructural", "x-dano": true, "x-grupo": "estribos", "x-elemento-ref": "subestructura.estribo_entrada.grietas", "x-orden": 1}, "estribo_entrada_socavacion": {"type": "integer", "minimum": 0, "maximum": 4, "title": "Estribo de Entrada: Socavación en cimentación", "description": "0=Sin daño, 1=Leve, 2=Moderada, 3=Exposición de cimentación (Anulación crítica IC), 4=Pérdida de apoyo", "x-dano": true, "x-grupo": "estribos", "x-elemento-ref": "subestructura.estribo_entrada.socavacion", "x-anulacion-critica": "socavacion_cimentacion", "x-orden": 2}, "estribo_salida_grietas": {"type": "integer", "minimum": 0, "maximum": 4, "title": "Estribo de Salida: Fisuras o grietas en cortina y aleros", "x-dano": true, "x-grupo": "estribos", "x-elemento-ref": "subestructura.estribo_salida.grietas", "x-orden": 3}, "estribo_salida_socavacion": {"type": "integer", "minimum": 0, "maximum": 4, "title": "Estribo de Salida: Socavación en cimentación", "x-dano": true, "x-grupo": "estribos", "x-elemento-ref": "subestructura.estribo_salida.socavacion", "x-anulacion-critica": "socavacion_cimentacion", "x-orden": 4}, "pilas_grietas": {"type": "integer", "minimum": 0, "maximum": 4, "title": "Pilas Intermedias: Fisuras o daño en fuste y cabezal", "x-dano": true, "x-grupo": "pilas", "x-elemento-ref": "subestructura.pilas.grietas", "x-orden": 5}, "pilas_socavacion": {"type": "integer", "minimum": 0, "maximum": 4, "title": "Pilas Intermedias: Socavación local alrededor del apoyo", "x-dano": true, "x-grupo": "pilas", "x-elemento-ref": "subestructura.pilas.socavacion", "x-anulacion-critica": "socavacion_cimentacion", "x-orden": 6}, "asentamiento_estructural": {"type": "integer", "minimum": 0, "maximum": 4, "title": "Asentamiento o Desplazamiento Estructural", "description": "Desnivel visible o rotación en apoyos (Anulación crítica IC si es severo).", "x-dano": true, "x-grupo": "cimentacion", "x-elemento-ref": "subestructura.cimentacion.asentamiento", "x-anulacion-critica": "asentamiento_estructura", "x-orden": 7}}}, "superestructura": {"type": "object", "title": "Sección 5: Super-estructura", "description": "Evaluación de vigas, losas de rodadura, juntas y aparatos de apoyo (escala 0 a 4). Alimenta el IC de P8.", "required": ["vigas_deformacion", "vigas_perdida_seccion", "vigas_ausencia_elemento", "losa_agrietamiento", "juntas_dilatacion", "aparatos_apoyo"], "properties": {"vigas_deformacion": {"type": "integer", "minimum": 0, "maximum": 4, "title": "Vigas Principales: Deflexión excesiva o pandeo", "x-dano": true, "x-grupo": "vigas", "x-elemento-ref": "superestructura.vigas.deformacion", "x-orden": 1}, "vigas_perdida_seccion": {"type": "integer", "minimum": 0, "maximum": 4, "title": "Vigas Principales: Elemento portante cortado o pérdida de sección", "description": "Corrosión profunda con pérdida de área de acero o concreto desprendido (Anulación crítica IC).", "x-dano": true, "x-grupo": "vigas", "x-elemento-ref": "superestructura.vigas.perdida_seccion", "x-anulacion-critica": "elemento_portante_cortado", "x-orden": 2}, "vigas_ausencia_elemento": {"type": "integer", "minimum": 0, "maximum": 4, "title": "Vigas Principales: Ausencia total de elemento portante", "description": "Viga o tensor faltante por impacto o colapso previo (Anulación crítica IC).", "x-dano": true, "x-grupo": "vigas", "x-elemento-ref": "superestructura.vigas.ausencia_elemento", "x-anulacion-critica": "ausencia_total_elemento", "x-orden": 3}, "losa_agrietamiento": {"type": "integer", "minimum": 0, "maximum": 4, "title": "Losa de Rodadura: Agrietamiento, baches o eflorescencia", "x-dano": true, "x-grupo": "losa", "x-elemento-ref": "superestructura.losa.agrietamiento", "x-orden": 4}, "juntas_dilatacion": {"type": "integer", "minimum": 0, "maximum": 4, "title": "Juntas de Dilatación: Deterioro del sello, filtración o desprendimiento", "x-dano": true, "x-grupo": "juntas", "x-elemento-ref": "superestructura.juntas.deterioro", "x-orden": 5}, "aparatos_apoyo": {"type": "integer", "minimum": 0, "maximum": 4, "title": "Aparatos de Apoyo: Deformación elastomérica, corrosión de placas o desalineamiento", "x-dano": true, "x-grupo": "apoyos", "x-elemento-ref": "superestructura.apoyos.deterioro", "x-orden": 6}}}, "elementos_no_estructurales": {"type": "object", "title": "Sección 6: Elementos No Estructurales", "description": "Barandas de protección, aceras peatonales, drenajes y accesos.", "required": ["barandas_danos", "aceras_danos", "drenajes_danos"], "properties": {"barandas_danos": {"type": "integer", "minimum": 0, "maximum": 4, "title": "Barandas: Daño por impacto, corrosión o tramos faltantes", "x-dano": true, "x-grupo": "seguridad_vial", "x-elemento-ref": "elementos_no_estructurales.barandas.danos", "x-orden": 1}, "aceras_danos": {"type": "integer", "minimum": 0, "maximum": 4, "title": "Aceras Peatonales: Desgaste, desprendimiento o fisuras", "x-dano": true, "x-grupo": "aceras", "x-elemento-ref": "elementos_no_estructurales.aceras.danos", "x-orden": 2}, "drenajes_danos": {"type": "integer", "minimum": 0, "maximum": 4, "title": "Drenajes y Bajantes: Obstrucción, corrosión o ausencia", "x-dano": true, "x-grupo": "drenajes", "x-elemento-ref": "elementos_no_estructurales.drenajes.danos", "x-orden": 3}}}, "caracteristicas_cauce": {"type": "object", "title": "Sección 7: Características del Cauce y Protección Hidráulica", "description": "Comportamiento del flujo de agua, encauzamiento y estabilidad de laderas.", "required": ["obstruccion_cauce", "alineamiento_flujo", "proteccion_margenes"], "properties": {"obstruccion_cauce": {"type": "integer", "minimum": 0, "maximum": 4, "title": "Obstrucción por Palizadas, Sedimentos o Escombros", "x-dano": true, "x-grupo": "hidraulica", "x-elemento-ref": "caracteristicas_cauce.obstruccion", "x-orden": 1}, "alineamiento_flujo": {"type": "integer", "minimum": 0, "maximum": 4, "title": "Alineamiento del Flujo Respecto a las Pilas", "description": "Ángulo de ataque desfavorable del río contra los apoyos.", "x-dano": true, "x-grupo": "hidraulica", "x-elemento-ref": "caracteristicas_cauce.alineamiento", "x-orden": 2}, "proteccion_margenes": {"type": "integer", "minimum": 0, "maximum": 4, "title": "Estado de Muros de Protección o Gaviones", "x-dano": true, "x-grupo": "hidraulica", "x-elemento-ref": "caracteristicas_cauce.proteccion_margenes", "x-orden": 3}}}, "otros": {"type": "object", "title": "Sección 8: Otros Factores, Señalización y Recomendaciones", "description": "Instalaciones colgadas, señalización vial preventiva y propuestas de intervención para P8.", "properties": {"servicios_publicos_colgados": {"type": "string", "title": "Instalaciones de Servicios Públicos", "description": "Tuberías de agua potable, drenajes o cableado eléctrico soportados en la estructura.", "x-elemento-ref": "otros.servicios_publicos", "x-orden": 1}, "senales_preventivas": {"type": "boolean", "title": "¿Cuenta con Señalización Preventiva de Carga / Velocidad?", "x-elemento-ref": "otros.senales_preventivas", "x-orden": 2}, "recomendaciones_inspector": {"type": "string", "title": "Recomendaciones Generales del Inspector", "description": "Observaciones técnicas cualitativas y urgencia sugerida.", "x-elemento-ref": "otros.recomendaciones", "x-orden": 3}}}}}'::jsonb,
    NULL,
    'ACTIVA',
